using System;using System.Data;using System.Text;using System.Web;using System.Web.UI;namespace AQOONHUB_SMS.Modules.Administration{public partial class AuditLogPage:Page{readonly SystemRepository r=new SystemRepository();int P{get{return Math.Max(1,(int?)(ViewState["P"])??1);}set{ViewState["P"]=Math.Max(1,value);}}int Pages{get{return Math.Max(1,(int?)(ViewState["Pages"])??1);}set{ViewState["Pages"]=value;}}protected void Page_Load(object s,EventArgs e){SystemAuthorization.DemandSecurity(this);if(!IsPostBack)Bind();}DateTime? D(string x){DateTime d;return DateTime.TryParse(x,out d)?d:(DateTime?)null;}void Dates(){if(D(txtFrom.Text).HasValue&&D(txtTo.Text).HasValue&&D(txtFrom.Text)>D(txtTo.Text))throw new InvalidOperationException("From date must not be after To date.");}void Bind(){try{Dates();int z=int.Parse(ddlPageSize.SelectedValue);PagedData p=r.AuditPage(D(txtFrom.Text),D(txtTo.Text),txtUser.Text.Trim(),txtModule.Text.Trim(),txtAction.Text.Trim(),P,z);Pages=Math.Max(1,(int)Math.Ceiling(p.Total/(double)z));if(P>Pages){P=Pages;Bind();return;}gv.DataSource=p.Rows;gv.DataBind();litTotal.Text=p.Total.ToString();litToday.Text=r.Audit(DateTime.Today,DateTime.Today,"","","").Rows.Count.ToString();litRisk.Text=litFailed.Text=r.Audit(D(txtFrom.Text),D(txtTo.Text),txtUser.Text.Trim(),txtModule.Text.Trim(),"LOGIN_FAILED").Rows.Count.ToString();litPage.Text="Page "+P+" of "+Pages+" · "+p.Total+" records";pgFirst.Enabled=pgPrev.Enabled=P>1;pgNext.Enabled=pgLast.Enabled=P<Pages;}catch(Exception ex){Error(ex.Message);}}protected void btnFilter_Click(object s,EventArgs e){P=1;Bind();}protected void btnReset_Click(object s,EventArgs e){txtFrom.Text=txtTo.Text=txtUser.Text=txtModule.Text=txtAction.Text="";P=1;Bind();}protected void PageSizeChanged(object s,EventArgs e){P=1;Bind();}protected void PageNav(object s,EventArgs e){string id=((Control)s).ID;P=id=="pgFirst"?1:id=="pgPrev"?P-1:id=="pgNext"?P+1:Pages;Bind();}protected void gv_RowCommand(object s,System.Web.UI.WebControls.GridViewCommandEventArgs e){long id;if(e.CommandName!="Details"||!long.TryParse(Convert.ToString(e.CommandArgument),out id))return;DataRow x=r.AuditDetail(id);if(x==null){Error("Audit event not found.");return;}litDetails.Text=F("Audit ID",x["AuditID"])+F("User",x["UserName"])+F("Date and Time",x["ActionTime"])+F("Module",x["Module"])+F("Action",x["Action"])+F("Description",Redact(x["Detail"].ToString()))+F("Status",x["Status"])+F("IP Address",x["IPAddress"])+F("User Agent","Unavailable")+F("Reference ID","Unavailable");pnlDetails.Visible=true;}protected void CloseDetails(object s,EventArgs e){pnlDetails.Visible=false;}protected void btnExport_Click(object s,EventArgs e){Dates();DataTable t=r.Audit(D(txtFrom.Text),D(txtTo.Text),txtUser.Text.Trim(),txtModule.Text.Trim(),txtAction.Text.Trim());var b=new StringBuilder("\uFEFFDate,User,Module,Action,Description,IP Address,Status\r\n");foreach(DataRow x in t.Rows)b.AppendLine(C(x["ActionTime"])+","+C(x["UserName"])+","+C(x["Module"])+","+C(x["Action"])+","+C(Redact(x["Detail"].ToString()))+","+C(x["IPAddress"])+","+C(x["Status"]));Response.Clear();Response.ContentType="text/csv";Response.AddHeader("Content-Disposition","attachment; filename=audit-log-"+DateTime.Now.ToString("yyyyMMdd-HHmm")+".csv");Response.BinaryWrite(Encoding.UTF8.GetBytes(b.ToString()));Response.End();}string Redact(string v){string l=(v??"").ToLowerInvariant();return l.Contains("password")||l.Contains("token")||l.Contains("connection string")||l.Contains("smtp")?"[Sensitive details redacted]":v;}string C(object o){string v=Convert.ToString(o);if(v.Length>0&&"=+-@".Contains(v.Substring(0,1)))v="'"+v;return "\""+v.Replace("\"","\"\"")+"\"";}string F(string k,object v){return "<div><dt>"+HttpUtility.HtmlEncode(k)+"</dt><dd>"+HttpUtility.HtmlEncode(Convert.ToString(v))+"</dd></div>";}void Error(string m){litMessage.Text="<div class='sys-error' role='alert'>"+HttpUtility.HtmlEncode(m)+"</div>";}}
}
